/* Shared platform composer. Evidence and drafts remain local until explicit Send. */
(() => {
  if(window.XENO_REPORT)return;
  const el=(tag,props={},text)=>{const n=document.createElement(tag);Object.assign(n,props);if(text!==undefined)n.textContent=text;return n;};
  const blocked=()=>/^\/(?:$|v3\/?$|home-v21(?:\/|$)|login(?:\/|$)|signup(?:\/|$)|auth(?:\/|$))/.test(location.pathname);
  const typing=event=>event.composedPath().some(n=>n instanceof Element&&(n.matches('input,textarea,select,[contenteditable]:not([contenteditable="false"]),[role="textbox"],[role="dialog"],dialog,.monaco-editor,.cm-editor,.xterm')||n.closest('.monaco-editor,.cm-editor,.xterm')));
  let current=null,capturing=false,opening=false;
  async function user(){const r=await fetch('/api/auth/me',{credentials:'same-origin',headers:{'x-xeno-surface':'xeno-web'}});if(!r.ok)throw new Error('Sign in to send a report.');const d=await r.json();if(!d.user?.id)throw new Error('Sign in to send a report.');return d.user;}
  const csrf=()=>{const m=document.cookie.match(/(?:^|;\s*)(?:__Host-xeno_csrf|xeno_csrf)=([^;]*)/);return m?decodeURIComponent(m[1]):null;};
  async function open(options={}){
    if(blocked()||capturing||opening)return;
    if(current){current.showModal();return;}
    opening=true;let actor;try{actor=await user();}finally{opening=false;}
    const product=location.pathname.startsWith('/workspace')?(location.pathname.match(/\/apps\/([a-z0-9-]+)/)?.[1]||'workspace'):(location.pathname.match(/^\/product\/([a-z0-9-]+)/)?.[1]||'platform');
    const client=window.XenoReportClient.createReportClient({baseUrl:location.origin,product,getAccessToken:()=>null,session:{getUserId:()=>String(actor.id),getCsrfToken:csrf}});
    const dialog=el('dialog',{className:'xreport'});current=dialog;
    const header=el('header'),heading=el('div');heading.append(el('h2',{},'Report to XENO'),el('p',{},`Sent as ${actor.username||actor.name||'your account'} · Shift+R`));
    const close=el('button',{type:'button','ariaLabel':'Close report'},'Close');header.append(heading,close);
    const main=el('main'),form=el('div'),aside=el('aside'),footer=el('footer'),error=el('p',{className:'xr-error',role:'alert'});
    const field=(label,tag,props)=>{const n=el(tag,props),wrap=el('label',{},label);wrap.append(n);form.append(wrap);return n;};
    const kind=field('Type','select',{});[['bug','Bug or issue'],['feature','Feature request'],['feedback','Feedback']].forEach(([value,label])=>kind.append(el('option',{value},label)));kind.value=options.kind||'bug';
    const title=field('In one line','input',{maxLength:200,value:options.title==='Contact support'?'':options.title||'',placeholder:'What went wrong?'});
    const body=field('What happened','textarea',{rows:4,maxLength:16000,placeholder:'What did you expect, and what happened instead?'});
    const repro=field('Steps to reproduce (optional)','textarea',{rows:3,maxLength:10000});
    const visibility=field('Who can read this','select',{});[['public','Everyone — Forum Feedback'],['private','Private — you and authorized XENO staff']].forEach(([value,label])=>visibility.append(el('option',{value},label)));visibility.value=options.title==='Contact support'?'private':options.visibility||'public';
    const audience=el('p',{className:'xr-note'});form.append(audience);
    const contextText=`Page: ${location.pathname}\nViewport: ${innerWidth} × ${innerHeight}\nLanguage: ${navigator.language}\nBrowser: ${navigator.userAgent}`;
    const context=field('Include the technical details below','input',{type:'checkbox',checked:true});const detail=el('pre',{},contextText);form.append(detail);
    const captureBar=el('div',{className:'xr-captures'}),files=el('input',{type:'file',accept:'image/png,image/jpeg,image/webp,video/webm,video/mp4',multiple:true,hidden:true}),list=el('div'),note=el('p',{className:'xr-note'},'Optional evidence · 3 files, 8 MiB each, 12 MiB total. Capture asks you to choose a tab. Review images and video for private information; pixels are not automatically redacted.');
    const attachments=[];
    const review=el('div',{className:'xr-review'}),preview=el('pre'),candidates=el('div',{className:'xr-candidates'});review.append(el('strong',{},'Review before sending'),el('p',{className:'xr-note'},'Text is redacted before review. Evidence below is sent exactly as previewed.'),preview,candidates);aside.append(review,list);
    let payload=null,submissionId=null,busy=false,uncertain=false,dirty=false;
    const invalidate=()=>{if(busy||uncertain)return;dirty=true;payload=null;submissionId=null;preview.textContent='Choose Review report to inspect the final text and evidence.';send.disabled=true;};
    const renderFiles=()=>{list.replaceChildren();attachments.forEach(a=>{const box=el('div',{className:'xr-attachment'}),row=el('div'),remove=el('button',{type:'button'},'Remove');remove.onclick=()=>{attachments.splice(attachments.indexOf(a),1);renderFiles();invalidate();};row.append(el('span',{},`${a.name} · ${(a.bytes/1024).toFixed(0)} KiB`),remove);const media=el(a.type.startsWith('image/')?'img':'video',{src:`data:${a.type};base64,${a.data}`,controls:true,alt:a.name});box.append(row,media);list.append(box);});};
    const add=items=>{if(attachments.length+items.length>3||[...attachments,...items].reduce((s,a)=>s+a.bytes,0)>12*1024*1024)throw new Error('Use at most 3 files and 12 MiB in total.');attachments.push(...items);renderFiles();invalidate();};
    const capture=async mode=>{if(busy||uncertain)return;error.textContent='';capturing=true;dialog.close();try{const a=mode==='record'?await window.XENO_REPORT_CAPTURE.record():await window.XENO_REPORT_CAPTURE.screenshot({area:mode==='area'});if(a)add([a]);}catch(e){error.textContent=e.message;}finally{capturing=false;dialog.showModal();}};
    [['Screenshot','screen'],['Select area','area'],['Record · 30s','record']].forEach(([label,mode])=>{const b=el('button',{type:'button'},label);b.onclick=()=>capture(mode);captureBar.append(b);});const attach=el('button',{type:'button'},'Attach file');attach.onclick=()=>files.click();captureBar.append(attach);files.onchange=async()=>{try{add(await Promise.all([...files.files].map(f=>window.XENO_REPORT_CAPTURE.attachment(f,f.name))));}catch(e){error.textContent=e.message;}files.value='';};form.append(note,captureBar,files,error);
    const renderPreview=p=>{preview.textContent=[p.visibility==='public'?'Public Forum report':'Private ticket',`Product: ${p.product}`,`Type: ${p.kind}`,p.joinShortId?`Adding to report ${p.joinShortId}`:'',p.title,'',p.body,p.context.repro?'\nSteps to reproduce\n'+p.context.repro:'',p.context.recentLog?.length?'\nIncluded technical details\n'+p.context.recentLog.join('\n'):'',p.context.attachments?.length?'\nEvidence below\n'+p.context.attachments.map(a=>`${a.name} · ${Math.ceil(a.bytes/1024)} KiB`).join('\n'):''].filter(x=>x!==undefined).join('\n');};
    const reviewButton=el('button',{type:'button'},'Review report'),send=el('button',{type:'button',disabled:true},'Send report'),recover=el('button',{type:'button',hidden:true},'Check submission');footer.append(el('span',{className:'xr-spacer'}),recover,reviewButton,send);
    const lock=value=>{busy=value;form.querySelectorAll('input,textarea,select,button').forEach(n=>n.disabled=value);list.querySelectorAll('button').forEach(n=>n.disabled=value);candidates.querySelectorAll('button').forEach(n=>n.disabled=value);reviewButton.disabled=value;close.disabled=value;send.disabled=value||!payload;};
    const finish=receipt=>{busy=false;dirty=false;uncertain=false;main.replaceChildren();const success=el('div',{className:'xr-success'});success.append(el('h3',{},receipt.private?'Private report sent':'Posted in Forum Feedback'),el('p',{},`Report ${receipt.shortId}. Replies will appear in your notifications.`));success.append(el('a',{href:receipt.private?`/workspace/community/My%20reports/${encodeURIComponent(receipt.shortId)}`:`/forum/t/${encodeURIComponent(receipt.shortId)}`},'Open report'));main.append(success);footer.replaceChildren();close.disabled=false;};
    reviewButton.onclick=async()=>{error.textContent='';lock(true);try{if(String((await user()).id)!==String(actor.id))throw new Error('Your account changed. Close this draft and reopen it with the current account.');const result=client.compose({kind:kind.value,visibility:visibility.value,title:title.value,body:body.value,context:{...(repro.value?{repro:repro.value}:{}),...(context.checked?{recentLog:contextText.split('\n')}:{}),attachments}});payload=result.payload;submissionId=crypto.randomUUID();renderPreview(payload);candidates.replaceChildren();send.disabled=false;if(visibility.value==='public'){const rows=await client.preflight(payload.title);for(const c of rows.slice(0,4)){const link=el('a',{href:`/forum/t/${encodeURIComponent(c.shortId)}`,target:'_blank',rel:'noopener'},c.title);const join=el('button',{type:'button'},'Add my report here');join.onclick=()=>{if(busy||uncertain)return;const joined=client.compose({...payload,context:payload.context,joinShortId:c.shortId});payload=joined.payload;submissionId=crypto.randomUUID();renderPreview(payload);};candidates.append(link,join);}}}catch(e){payload=null;send.disabled=true;error.textContent=e.message;}finally{lock(false);}};
    send.onclick=async()=>{if(!payload||(busy&&!uncertain))return;uncertain=false;const sendingPayload=payload,sendingId=submissionId;lock(true);error.textContent='';try{if(String((await user()).id)!==String(actor.id))throw new Error('Your account changed. Reopen the report to review it again.');finish(await client.submit(sendingPayload,{submissionId:sendingId}));}catch(e){error.textContent=e.message;if(e.code==='report_submission_uncertain'){uncertain=true;recover.hidden=false;send.textContent='Retry same submission';}}finally{lock(uncertain);if(uncertain){send.disabled=false;recover.disabled=false;}}};
    recover.onclick=async()=>{try{const r=await client.recover(submissionId);if(r.state==='committed')finish(r.receipt);else error.textContent='No committed report was found. Retry uses the same submission ID, so it cannot create a second copy.';}catch(e){error.textContent=e.message;}};
    const dismiss=()=>{if(busy||uncertain){error.textContent='Check or retry this submission before closing; its result is not confirmed.';return;}if(dirty&&close.textContent!=='Discard draft'){close.textContent='Discard draft';error.textContent='Your draft has not been sent. Press Discard draft to close it.';return;}dialog.close();dialog.remove();current=null;};close.onclick=dismiss;dialog.oncancel=e=>{e.preventDefault();dismiss();};
    form.addEventListener('input',invalidate);form.addEventListener('change',()=>{invalidate();audience.textContent=visibility.value==='public'?'Public and permanent. Anyone can read this report and its evidence.':'Private ticket. Only you and authorized XENO staff or product agents can read it.';});form.dispatchEvent(new Event('change'));dirty=false;
    main.append(form,aside);dialog.append(header,main,footer);document.body.append(dialog);dialog.showModal();title.focus();
  }
  window.XENO_REPORT={open,typing};
  if(!blocked()&&window.parent===window&&!/^\/workspace(?:\/|$)/.test(location.pathname))user().then(()=>{const b=el('button',{type:'button',className:'xr-launcher',title:'Report a problem · Shift+R'},'Report a problem');b.onclick=()=>{if(!blocked())open().catch(e=>console.warn(e.message));};document.body.append(b);}).catch(()=>{});
  addEventListener('keydown',event=>{if(blocked()||capturing||event.defaultPrevented||event.repeat||event.isComposing||!event.shiftKey||event.ctrlKey||event.altKey||event.metaKey||event.key.toLowerCase()!=='r'||typing(event)||document.querySelector('dialog[open],[aria-modal="true"]'))return;event.preventDefault();if(window.parent!==window){try{if(window.parent.location.origin===location.origin&&/^\/workspace(?:\/|$)/.test(window.parent.location.pathname)){window.parent.postMessage({source:'xeno-chat',type:'report-open'},location.origin);return;}}catch{}}open().catch(e=>{window.XW?.toast?.(e.message);console.warn('Report:',e.message);});});
})();
